/// やることリストの1件。
public struct Todo: Sendable, Equatable {
    public var title: String
    public var isDone: Bool

    public init(title: String, isDone: Bool = false) {
        self.title = title
        self.isDone = isDone
    }
}

public struct TodoList: Sendable {
    public var items: [Todo]

    public init(items: [Todo] = []) { self.items = items }

    /// 登録されている件数(完了済みも含む)。
    public var count: Int { items.count }
}

initialFiles.Sources/Todo/TodoSummary.swift:
/// 一覧の上に出す要約の1行。例: "全 3 件"
public enum TodoSummary {
    public static func line(for list: TodoList) -> String {
        "全 \(list.count) 件"
    }
}

