import Testing
@testable import Todo

@Test func summaryShowsRemaining() {
    let list = TodoList(items: [Todo(title: "買い物"), Todo(title: "洗濯", isDone: true), Todo(title: "掃除")])
    #expect(TodoSummary.line(for: list) == "全 3 件・残り 2 件")
