import Testing
@testable import Todo

/// 全部終わっていれば残り 0 件。
@Test func allDoneShowsZeroRemaining() {
    let list = TodoList(items: [Todo(title: "a", isDone: true), Todo(title: "b", isDone: true)])
    #expect(list.remaining == 0)
    #expect(TodoSummary.line(for: list) == "全 2 件・残り 0 件")
}

/// 空のリスト。
@Test func emptyList() {
    #expect(TodoList().remaining == 0)
    #expect(TodoSummary.line(for: TodoList()) == "全 0 件・残り 0 件")
}

